\begin{tikzpicture}[x=7.2mm,y=7.2mm,font=\rmfamily\fontsize{10}{12}\selectfont]
\special{dvisvgm:raw <metadata data-graph-strokes="1"/>}
\definecolor{graphGrid}{HTML}{CCCCCC}
\foreach \x in {4.5,5.5,...,9.5} {\draw[draw=graphGrid,line width=0.15pt,dash pattern=on 1pt off 1.5pt] (\x,0)--(\x,7);}
\foreach \y in {0.5,1.5,...,6.5} {\draw[draw=graphGrid,line width=0.15pt,dash pattern=on 1pt off 1.5pt] (4,\y)--(10,\y);}
\foreach \x in {4,5,...,10} {\draw[draw=graphGrid,line width=0.25pt,dash pattern=on 1pt off 1.5pt] (\x,0)--(\x,7);}
\foreach \y in {0,1,...,7} {\draw[draw=graphGrid,line width=0.25pt,dash pattern=on 1pt off 1.5pt] (4,\y)--(10,\y);}
\foreach \score/\frequency in {5/2,6/5,7/6,8/4,9/3} {\draw[black,line width=0.8pt] ({\score-0.5},0) rectangle ({\score+0.5},\frequency);}
\draw[black,line width=0.5pt] (4,0)--(10.1,0);
\draw[black,line width=0.5pt] (4,0)--(4,7.2);
\foreach \x in {5,6,...,9} {\draw[black,line width=0.4pt] (\x,0)--++(0,-1mm) node[anchor=north,inner sep=1pt,font=\rmfamily\fontsize{8.5}{10}\selectfont] {\special{dvisvgm:raw <g data-graph-text="tick">}\x\special{dvisvgm:raw </g>}};}
\foreach \y in {0,1,...,7} {\draw[black,line width=0.4pt] (4,\y)--++(-1mm,0) node[anchor=east,inner sep=1pt,font=\rmfamily\fontsize{8.5}{10}\selectfont] {\special{dvisvgm:raw <g data-graph-text="tick">}\y\special{dvisvgm:raw </g>}};}
\node[anchor=north,font=\rmfamily\itshape\fontsize{10}{12}\selectfont] at (7,-1.05) {Score};
\node[rotate=90,font=\rmfamily\itshape\fontsize{10}{12}\selectfont] at (2.7,3.5) {Frequency};
\end{tikzpicture}
